// FPGA top level for the SW / LEDR / HEX board (generated by LSE)
//   inputs  -> switches  (D3=SW[3], D2=SW[2], D1=SW[1], D0=SW[0])
//   outputs -> LEDs      (a=LEDR[0], b=LEDR[1], c=LEDR[2], d=LEDR[3], e=LEDR[4], f=LEDR[5], g=LEDR[6])
//   HEX0    -> decoder outputs a-g drive the segments
`timescale 1ns / 1ps

module top (
    input  wire        CLOCK_50,
    input  wire [9:0]  SW,
    input  wire [3:0]  KEY_N,
    output wire [9:0]  LEDR,
    output wire [6:0]  HEX0_N,
    output wire [6:0]  HEX1_N,
    output wire [6:0]  HEX2_N,
    output wire [6:0]  HEX3_N,
    output wire [6:0]  HEX4_N,
    output wire [6:0]  HEX5_N
);
    wire [6:0] y;   // outputs of the generated logic

    bcd7seg core (
        .D3(SW[3]),
        .D2(SW[2]),
        .D1(SW[1]),
        .D0(SW[0]),
        .a(y[0]),
        .b(y[1]),
        .c(y[2]),
        .d(y[3]),
        .e(y[4]),
        .f(y[5]),
        .g(y[6])
    );

    assign LEDR   = {3'b0, y};
    assign HEX0_N = ~y[6:0];   // segments are active low (0 = on)
    assign HEX1_N = 7'h7F;     // unused displays off
    assign HEX2_N = 7'h7F;
    assign HEX3_N = 7'h7F;
    assign HEX4_N = 7'h7F;
    assign HEX5_N = 7'h7F;
    // CLOCK_50 and KEY_N are not used
endmodule

// Structural Verilog generated by LSE (Logic Synthesis Engine)
// Design: bcd7seg   inputs: D3 D2 D1 D0   style: AND-OR
//   a = D3 + D1 + D2*D0 + D2'*D0'
//   b = D2' + D1*D0 + D1'*D0'
//   c = D2 + D1' + D0
//   d = D3 + D2'*D1 + D2'*D0' + D1*D0' + D2*D1'*D0
//   e = D2'*D0' + D1*D0'
//   f = D3 + D2*D1' + D2*D0' + D1'*D0'
//   g = D3 + D2*D1' + D2*D0' + D2'*D1
// Gates: 19  transistors: 126  levels: 3  delay: 6.50 tau
`timescale 1ns / 1ps

module bcd7seg (
    input  wire D3,
    input  wire D2,
    input  wire D1,
    input  wire D0,
    output wire a,
    output wire b,
    output wire c,
    output wire d,
    output wire e,
    output wire f,
    output wire g
);

    wire w0, D2_n, D0_n, w3, w4, D1_n, w6, w7;
    wire w8, w9, w10, w11;

    and  g0 (w0, D2, D0);
    not  g1 (D2_n, D2);
    not  g2 (D0_n, D0);
    and  g3 (w3, D2_n, D0_n);
    or   g4 (a, D3, D1, w0, w3);
    and  g5 (w4, D1, D0);
    not  g6 (D1_n, D1);
    and  g7 (w6, D1_n, D0_n);
    or   g8 (b, D2_n, w4, w6);
    or   g9 (c, D2, D1_n, D0);
    and  g10 (w7, D2_n, D1);
    and  g11 (w8, D1, D0_n);
    and  g12 (w9, D2, D1_n, D0);
    or   g13 (d, D3, w7, w3, w8, w9);
    or   g14 (e, w3, w8);
    and  g15 (w10, D2, D1_n);
    and  g16 (w11, D2, D0_n);
    or   g17 (f, D3, w10, w11, w6);
    or   g18 (g, D3, w10, w11, w7);

endmodule
